insert into public.messinho_language_knowledge
(entry_key,version,language_code,entry_type,topic,title,content,tags,level,knowledge_status,provenance_type,created_by)
values
('ar.grammar.agreement_clauses',1,'ar','grammar','النحو','تركيب الجملة والمطابقة','{"terms":[{"term":"الجملة الاسمية","meaning_de":"Nominalsatz"},{"term":"الجملة الفعلية","meaning_de":"Verbalsatz"},{"term":"الإضافة","meaning_de":"Genitivverbindung"},{"term":"حرف الجر","meaning_de":"Präposition"}],"examples":[{"text":"يلعب اللاعب اليوم.","meaning":"جملة فعلية تبدأ بالفعل."},{"text":"اللاعب سريع.","meaning":"جملة اسمية."},{"text":"مهارات اللاعب مهمة.","meaning":"تركيب إضافة."}],"explanation":"تأتي الجملة العربية غالبا اسمية أو فعلية. قد يبدأ التركيب بالفعل أو بالاسم، ويؤثر ذلك في المطابقة بين الفعل والفاعل. تتبع الصفة الموصوف في التعريف والتنكير والجنس والعدد والإعراب. الإضافة تربط اسما بمضاف إليه.","grammar_notes":["Die Wortstellung VSO und SVO ist kontextabhängig.","Adjektivkongruenz und Definitheit getrennt prüfen."]}'::jsonb,ARRAY['النحو','الجملة الاسمية','الجملة الفعلية','المطابقة','الإضافة','حروف الجر'],'intermediate','active','original_authored','messinho_original'),
('ar.lexicon.football_core',1,'ar','lexicon','مصطلحات كرة القدم','مفردات كرة القدم والكشافة','{"terms":[{"term":"مدافع مركزي","meaning_de":"Innenverteidiger"},{"term":"ظهير","meaning_de":"Außenverteidiger"},{"term":"لاعب ارتكاز","meaning_de":"defensiver Mittelfeldspieler"},{"term":"لاعب وسط","meaning_de":"Mittelfeldspieler"},{"term":"جناح","meaning_de":"Flügelspieler"},{"term":"مهاجم","meaning_de":"Stürmer"},{"term":"ضغط عال","meaning_de":"hohes Pressing"},{"term":"تمرير بيني","meaning_de":"Steilpass"},{"term":"مساحة خلف الدفاع","meaning_de":"Raum hinter der Abwehr"},{"term":"تقييم اللاعب","meaning_de":"Spielerbewertung"}],"examples":[{"text":"يحمي لاعب الارتكاز المساحة أمام الدفاع.","meaning":"Taktische Rollenbeschreibung."},{"text":"ينطلق الجناح خلف الظهير.","meaning":"Lauf in den Raum hinter dem Außenverteidiger."}],"explanation":"مفردات عربية فصحى أصلية لمجال كرة القدم والكشافة. قد تختلف أسماء المراكز والتعابير بين البلدان والأنظمة التكتيكية؛ يجب فهم المصطلح ضمن السياق.","grammar_notes":["Modern Standard Arabic bleibt getrennt von tunesischer Derja."]}'::jsonb,ARRAY['كرة القدم','الكشافة','المراكز','التكتيك','تحليل الأداء'],'foundational','active','original_authored','messinho_original'),
('ar.morphology.roots_patterns',1,'ar','grammar','الصرف','الجذور والأوزان والتصريف','{"terms":[{"term":"لَعِبَ / يَلْعَبُ","meaning_de":"Vergangenheit und Gegenwart des Verbs spielen"},{"term":"لاعب / لاعبة","meaning_de":"männlicher und weiblicher Spieler"},{"term":"لاعبون / لاعبين","meaning_de":"Pluralformen mit unterschiedlicher Kasusfunktion"},{"term":"مكتوب","meaning_de":"Partizip passiv; geschrieben"}],"examples":[{"text":"يلعب اللاعب في الوسط.","meaning":"Verbform und bestimmter maskuliner Spieler."},{"text":"اللاعبة سريعة.","meaning":"Femininum und Adjektivkongruenz."},{"text":"اللاعبون يتدربون.","meaning":"Männlicher Plural und Verbkongruenz."}],"explanation":"تعتمد العربية الفصحى في كثير من مفرداتها على جذور صرفية وأوزان. يتغير شكل الفعل بحسب الزمن والضمير، وتتغير الأسماء والصفات بحسب الجنس والعدد والحالة الإعرابية. لا يكفي تشابه الجذر وحده لتحديد معنى الكلمة دون السياق.","grammar_notes":["Wurzel und Muster sind Hinweise, keine vollständige Bedeutungsdefinition.","Kasusendungen können in gesprochener Sprache fehlen, bleiben aber in formeller Grammatik relevant."]}'::jsonb,ARRAY['الصرف','الجذر','الوزن','تصريف الفعل','المذكر','المؤنث','المثنى','الجمع'],'foundational','active','original_authored','messinho_original'),
('ar.semantics.discourse',1,'ar','pragmatics','الدلالة والتداولية','النفي والاحتمال والروابط','{"terms":[{"term":"لا","meaning_de":"Verneinung im Präsens oder allgemeine Negation je nach Konstruktion"},{"term":"لم","meaning_de":"Negiert typischerweise eine vergangene Handlung mit jussivischer Verbform"},{"term":"لن","meaning_de":"Verneint typischerweise eine zukünftige Handlung"},{"term":"ليس","meaning_de":"Negiert nominale oder bestimmte verbale Prädikationen"},{"term":"ربما","meaning_de":"vielleicht; möglicherweise"},{"term":"لكن","meaning_de":"aber; jedoch"}],"examples":[{"text":"لا يلعب اليوم.","meaning":"Er spielt heute nicht."},{"text":"لم يلعب أمس.","meaning":"Er hat gestern nicht gespielt."},{"text":"ربما يتحسن، لكنه يحتاج إلى وقت.","meaning":"Unsicherheit und Kontrast."}],"explanation":"تحدد أدوات النفي والاحتمال والربط معنى الجملة وزمنها ودرجة اليقين. لا تعني أدوات النفي الشيء نفسه: لا، لم، لن، ليس لها وظائف مختلفة. كلمات مثل ربما وقد تشير إلى احتمال أو إمكان بحسب السياق. يجب الحفاظ على النفي والتحفظ والتباين في الترجمة.","grammar_notes":["Unterschiedliche Negationspartikeln nicht zu einem einzigen deutschen ''nicht'' zusammenziehen.","Modalität nicht als Gewissheit ausgeben."]}'::jsonb,ARRAY['الدلالة','التداولية','النفي','ربما','لكن','قد','لم','لن'],'intermediate','active','original_authored','messinho_original'),
('ar-tn.grammar.questions_clauses',1,'ar-tn','grammar','تركيب الدارجة','الأسئلة وترتيب الجملة','{"terms":[{"term":"شنوة / chnowa","meaning_de":"was?"},{"term":"وين / win","meaning_de":"wo?"},{"term":"علاش / 3lech","meaning_de":"warum?"},{"term":"كيفاش / kifech","meaning_de":"wie?"},{"term":"وقتاش / wa9tech","meaning_de":"wann?"},{"term":"قداش / 9addech","meaning_de":"wie viel oder wie viele?"}],"examples":[{"text":"شنوة مركز اللاعب؟","meaning":"Welche Position spielt der Spieler?"},{"text":"وقتاش يلعب الفريق؟","meaning":"Wann spielt die Mannschaft?"},{"text":"علاش ما لعبش اليوم؟","meaning":"Warum hat er heute nicht gespielt?"}],"explanation":"تستعمل الدارجة التونسية أدوات استفهام مثل chnowa وwin و3lech وkifech وwa9tech و9addech. غالبا يعتمد ترتيب الجملة على الموضوع والسياق، ويمكن أن تظهر ضمائر متصلة وحروف جر في شكل مختصر. قد تدخل كلمات فرنسية في الجملة دون أن يتغير الإطار التونسي.","grammar_notes":["Schreibweisen variieren: chnowa/chnoua, kifech/kifesh, taw/tawa.","Bei unklarer Arabizi-Schreibweise Original bewahren und nicht übermäßig normalisieren."]}'::jsonb,ARRAY['Derja','أسئلة','chnowa','win','3lech','kifech','wa9tech'],'foundational','active','original_authored','messinho_original'),
('ar-tn.lexicon.football_core',1,'ar-tn','lexicon','مصطلحات الكورة بالدارجة','مفردات تونسية لكرة القدم والكشافة','{"terms":[{"term":"لاعب / joueur / joueur","meaning_de":"Spieler"},{"term":"فريق / équipe","meaning_de":"Mannschaft oder Team"},{"term":"مدرب / entraîneur","meaning_de":"Trainer"},{"term":"مدافع / défenseur","meaning_de":"Verteidiger"},{"term":"وسط / milieu","meaning_de":"Mittelfeld"},{"term":"مهاجم / attaquant","meaning_de":"Stürmer"},{"term":"ماتش / match","meaning_de":"Spiel"},{"term":"تيران / terrain","meaning_de":"Spielfeld"},{"term":"تبديلة / changement","meaning_de":"Auswechslung"},{"term":"تقييم / évaluation","meaning_de":"Bewertung"}],"examples":[{"text":"الjoueur هذا يلعب milieu.","meaning":"Spieler spielt im Mittelfeld; Code-Switching."},{"text":"المدرب عمل changement.","meaning":"Der Trainer nahm eine Auswechslung vor."}],"explanation":"مجموعة أصلية أولية من مفردات كرة القدم كما يمكن أن تظهر في محادثة تونسية. توجد اختلافات محلية وطرق كتابة متعددة؛ بعض المصطلحات تتبدل بين الدارجة والفرنسية والإنجليزية.","grammar_notes":["Wortwahl und Schreibung regional gegenprüfen; nicht als vollständiges tunesisches Wörterbuch ausgeben."]}'::jsonb,ARRAY['Derja','كورة','football','joueur','équipe','tactique','scouting'],'foundational','active','original_authored','messinho_original'),
('ar-tn.morphology.negation_clitics',1,'ar-tn','grammar','صرف الدارجة','تصريف الأفعال والنفي والضمائر المتصلة','{"terms":[{"term":"نلعب / nal3ab","meaning_de":"ich spiele"},{"term":"ما نلعبش / ma nal3abch","meaning_de":"ich spiele nicht"},{"term":"يعرفني / ya3refni","meaning_de":"er kennt mich"},{"term":"معاه / m3ah","meaning_de":"mit ihm oder bei ihm, je nach Kontext"}],"examples":[{"text":"ما فهمتش السؤال.","meaning":"Ich habe die Frage nicht verstanden."},{"text":"هو يعرفني من الفريق.","meaning":"Er kennt mich aus dem Team."},{"text":"ما لعبوش البارح.","meaning":"Sie haben gestern nicht gespielt."}],"explanation":"تستعمل الدارجة التونسية صيغ أفعال قريبة من العربية مع اختلافات صوتية وصرفية. من أنماط النفي الشائعة وضع ma قبل الفعل و-sh في آخره، لكن الاستعمال يتغير حسب الفعل والسياق. قد تلتحق الضمائر بالفعل أو بحروف الجر. الكتابة بالعربية واللاتينية غير موحدة.","grammar_notes":["Arabizi-Ziffern sind Buchstabenersatz innerhalb von Wörtern, keine Zahlenwerte.","Die ma...ch-Struktur ist häufig, aber nicht für jede Negationsform universell."]}'::jsonb,ARRAY['Derja','صرف','النفي','ma ch','ma...ch','ضمائر','Arabizi'],'foundational','active','original_authored','messinho_original'),
('ar-tn.semantics.codeswitching',1,'ar-tn','pragmatics','الدلالة والتداولية','تبديل اللغة والسياق والمعنى','{"terms":[{"term":"باهي / behi","meaning_de":"gut, okay oder passend je nach Situation"},{"term":"برشا / barcha","meaning_de":"viel oder sehr"},{"term":"يمكن / ynajjem","meaning_de":"kann oder könnte je nach Konstruktion"},{"term":"أما / ama","meaning_de":"aber; dagegen"},{"term":"مازال / mazal","meaning_de":"noch; weiterhin; noch nicht je nach Form"}],"examples":[{"text":"اللاعب هذا behi ama يلزمو وقت.","meaning":"Der Spieler ist gut, braucht aber noch Zeit."},{"text":"يمكن يعمل progrès.","meaning":"Code-Switching mit französischem Lehnwort; könnte Fortschritte machen."},{"text":"مازال موش prêt.","meaning":"Er ist noch nicht bereit; Negation bleibt erhalten."}],"explanation":"تخلط المحادثة التونسية أحيانا بين الدارجة والفرنسية والعربية الفصحى والإنجليزية. الانتقال بين اللغات لا يعني بالضرورة خطأ أو تغييرا في المعنى. يجب فهم الكلمة المستعارة ضمن الجملة، والحفاظ على النفي والتهذيب والسخرية ودرجة اليقين.","grammar_notes":["Derja nicht ungefragt in Hocharabisch umformen.","Bei französischen Lehnwörtern ist die Funktion im Satz wichtiger als die Herkunft."]}'::jsonb,ARRAY['Derja','code switching','français','Arabizi','السياق','النفي','الاحتمال'],'intermediate','active','original_authored','messinho_original'),
('de.grammar.complex_clauses',1,'de','grammar','Satzbau','Nebensätze, Fragen und Satzklammer','{"terms":[{"term":"weil","meaning_de":"leitet häufig einen begründenden Nebensatz ein"},{"term":"obwohl","meaning_de":"leitet einen konzessiven Nebensatz ein"},{"term":"damit","meaning_de":"leitet häufig einen Finalsatz ein"},{"term":"ob","meaning_de":"leitet eine indirekte Entscheidungsfrage ein"}],"examples":[{"text":"Der Spieler trainiert heute.","meaning":"Hauptsatz mit Verbzweitstellung."},{"text":"..., weil der Spieler heute trainiert.","meaning":"Nebensatz mit Verbendstellung."},{"text":"Ich möchte wissen, ob er morgen spielt.","meaning":"Indirekte Entscheidungsfrage."}],"explanation":"Im Hauptsatz steht das finite Verb typischerweise an zweiter Satzposition; im Entscheidungsfragesatz meist an erster Position. In vielen Nebensätzen steht das finite Verb am Ende. Modalverben, Perfekt und trennbare Verben bilden eine Satzklammer. Indirekte Fragen übernehmen die Verbendstellung.","grammar_notes":["Kommas strukturieren Nebensätze, ändern aber nicht deren Verbposition.","Bei mehreren Verben hängt die Reihenfolge von Tempus, Modalität und Konstruktion ab."]}'::jsonb,ARRAY['Nebensatz','Verbendstellung','Satzklammer','indirekte Frage','Konjunktion'],'intermediate','active','original_authored','messinho_original'),
('de.lexicon.football_core',1,'de','lexicon','Fußballfachsprache','Grundwortschatz Fußball und Scouting','{"terms":[{"term":"Innenverteidiger","meaning_de":"zentraler Abwehrspieler"},{"term":"Außenverteidiger","meaning_de":"Verteidiger auf einer Außenbahn"},{"term":"Sechser","meaning_de":"defensiv orientierter zentraler Mittelfeldspieler"},{"term":"Achter","meaning_de":"zentraler Mittelfeldspieler mit Verbindungsspiel"},{"term":"Zehner","meaning_de":"offensiver Mittelfeldspieler hinter der Spitze"},{"term":"Flügelspieler","meaning_de":"Spieler auf einer offensiven Außenposition"},{"term":"Pressing","meaning_de":"koordiniertes Anlaufen zur Balleroberung"},{"term":"Tiefenlauf","meaning_de":"Laufbewegung in den Raum hinter die Abwehr"},{"term":"Spielverlagerung","meaning_de":"Verlagerung des Ballbesitzes auf die andere Spielfeldseite"},{"term":"Anschlussaktion","meaning_de":"Aktion unmittelbar nach einer vorherigen Aktion"}],"examples":[{"text":"Der Sechser sichert den Raum vor der Abwehr.","meaning":"Positions- und taktischer Kontext."},{"text":"Der Flügelspieler startet einen Tiefenlauf.","meaning":"Offensive Laufbewegung."}],"explanation":"Original formulierter deutscher Fußballwortschatz. Positionsbezeichnungen und taktische Begriffe können je nach Verein und System variieren; bei mehrdeutigen Abkürzungen ist der Kontext maßgeblich.","grammar_notes":["Positionsnamen sind Rollenbeschreibungen, keine unveränderlichen Spielerattribute."]}'::jsonb,ARRAY['Fußball','Scouting','Positionen','Taktik','Leistungsanalyse'],'foundational','active','original_authored','messinho_original'),
('de.morphology.inflection',1,'de','grammar','Morphologie','Flexion von Nomen, Artikeln, Adjektiven und Verben','{"terms":[{"term":"dem Spieler","meaning_de":"Dativ Singular; häufig Empfänger oder Betroffener"},{"term":"den Spieler","meaning_de":"Akkusativ Singular maskulin"},{"term":"mit schnellen Spielern","meaning_de":"Dativ Plural mit Adjektivendung -en"},{"term":"spielte / hat gespielt","meaning_de":"Präteritum und Perfekt"},{"term":"Spielerentwicklung","meaning_de":"Zusammengesetztes Nomen; Bedeutung aus den Bestandteilen erschließen"}],"examples":[{"text":"Der Trainer gibt dem jungen Spieler einen Rat.","meaning":"Nominativ, Dativ und Akkusativ werden durch Artikel und Endungen markiert."},{"text":"Die Spieler haben intensiv trainiert.","meaning":"Plural und Perfekt."},{"text":"Eine bessere Lösung wäre möglich.","meaning":"Adjektivflexion und Konjunktiv II."}],"explanation":"Deutsch markiert grammatische Beziehungen durch Flexion. Artikel, Pronomen und Adjektive richten sich nach Genus, Numerus und Kasus; Verben nach Person, Numerus, Zeit und Modus. Starke, schwache und gemischte Deklination sowie unregelmäßige Verben müssen im Satzkontext erkannt werden.","grammar_notes":["Kasus nicht allein aus der Wortstellung ableiten.","Adjektivendungen hängen von Artikelwort, Kasus, Genus und Numerus ab.","Trennbare Verben können den Verbzusatz ans Satzende stellen."]}'::jsonb,ARRAY['Morphologie','Kasus','Genus','Numerus','Adjektivdeklination','Verbkonjugation'],'foundational','active','original_authored','messinho_original'),
('de.semantics.discourse',1,'de','pragmatics','Semantik und Diskurs','Modalpartikeln, Negation und Bedeutungsnuancen','{"terms":[{"term":"doch","meaning_de":"kann Widerspruch, Erinnerung oder Bestätigung ausdrücken"},{"term":"noch","meaning_de":"kann Fortdauer, Zusatz oder eine offene Erwartung markieren"},{"term":"erst","meaning_de":"markiert häufig einen späteren oder begrenzten Zeitpunkt"},{"term":"schon","meaning_de":"kann zeitliche Frühzeitigkeit oder eine eingeräumte Aussage markieren"},{"term":"eigentlich","meaning_de":"kann eine Präzisierung, Einschränkung oder Themenverschiebung anzeigen"}],"examples":[{"text":"Er ist noch nicht bereit.","meaning":"Der Zustand ist zum Bezugszeitpunkt nicht erreicht."},{"text":"Er ist schon gut, aber noch nicht konstant.","meaning":"Positive Einschätzung mit Einschränkung."},{"text":"Das ist doch möglich.","meaning":"Kontextabhängige Erwartung oder Einwand."}],"explanation":"Deutsche Partikeln steuern Erwartung, Kontrast, Korrektur und Gesprächshaltung. Ihre Bedeutung ist stark kontextabhängig. Negation kann einzelne Satzteile oder die ganze Aussage betreffen. MESSINHO muss Reichweite und Fokus erhalten, statt jede Aussage als absolute Zustimmung oder Ablehnung zu behandeln.","grammar_notes":["Negationsfokus bestimmen: nicht jeder Satzteil wird automatisch verneint.","Modalpartikeln nicht isoliert wörtlich übersetzen."]}'::jsonb,ARRAY['eigentlich','doch','noch','schon','erst','Negation','Modalität','Kontrast'],'intermediate','active','original_authored','messinho_original'),
('en.grammar.clauses_questions',1,'en','grammar','Clause structure','Questions, auxiliaries and subordinate clauses','{"terms":[{"term":"do-support","meaning_de":"Hilfsverb do für Fragen und Verneinungen ohne anderes Hilfsverb"},{"term":"who","meaning_de":"Relativ- oder Fragepronomen für Personen"},{"term":"which","meaning_de":"Relativ- oder Fragepronomen für Dinge und Auswahl"}],"examples":[{"text":"Does the player train every day?","meaning":"Do-support and subject–auxiliary inversion."},{"text":"The player who joined in July is improving.","meaning":"Restrictive relative clause."},{"text":"I know that he is ready.","meaning":"That-clause as complement."}],"explanation":"English questions commonly use auxiliary inversion: the auxiliary precedes the subject. When no auxiliary is present, do-support is used in many present and past simple questions and negatives. Relative and subordinate clauses add information while preserving their own internal structure.","grammar_notes":["After do/does/did, use the base verb.","Embedded questions usually keep statement word order: I know where he plays."]}'::jsonb,ARRAY['question formation','auxiliary','relative clause','word order','subordinate clause'],'intermediate','active','original_authored','messinho_original'),
('en.lexicon.football_core',1,'en','lexicon','Football terminology','Core football and scouting vocabulary','{"terms":[{"term":"centre-back","meaning_de":"Innenverteidiger"},{"term":"full-back","meaning_de":"Außenverteidiger"},{"term":"holding midfielder","meaning_de":"defensiv orientierter zentraler Mittelfeldspieler"},{"term":"box-to-box midfielder","meaning_de":"zentraler Mittelfeldspieler mit Aufgaben in beiden Strafräumen"},{"term":"attacking midfielder","meaning_de":"offensiver Mittelfeldspieler"},{"term":"wide forward","meaning_de":"offensiver Außenspieler"},{"term":"pressing trigger","meaning_de":"Auslöser für gemeinsames Pressing"},{"term":"through ball","meaning_de":"Steilpass in den Raum"},{"term":"overlap","meaning_de":"Hinterlaufen eines Mitspielers"},{"term":"progressive pass","meaning_de":"Pass, der den Ball deutlich in Richtung gegnerisches Tor bewegt"}],"examples":[{"text":"The holding midfielder protects the space in front of the defence.","meaning":"Tactical role description."},{"text":"The full-back makes an overlap.","meaning":"Movement outside a teammate."}],"explanation":"Original-authored English football vocabulary. Position names can refer to different roles in different formations; interpret them in tactical context.","grammar_notes":["Use the role in the observed formation, not a generic label alone."]}'::jsonb,ARRAY['football','scouting','positions','tactics','performance analysis'],'foundational','active','original_authored','messinho_original'),
('en.morphology.inflection',1,'en','grammar','Morphology','English inflection and word formation','{"terms":[{"term":"plays / played / playing","meaning_de":"dritte Person Singular, Vergangenheit und Verlaufsform"},{"term":"better / best","meaning_de":"unregelmäßige Steigerung"},{"term":"development","meaning_de":"Ableitung aus develop"},{"term":"centre-back","meaning_de":"zusammengesetzte Positionsbezeichnung"}],"examples":[{"text":"The player trains every day.","meaning":"Third-person singular agreement."},{"text":"They played yesterday.","meaning":"Regular past tense."},{"text":"She is improving.","meaning":"Progressive aspect."}],"explanation":"English uses relatively limited inflection compared with German, but nouns, verbs, pronouns and adjectives still carry grammatical information. Regular plural -s, third-person singular -s, past -ed and progressive -ing interact with irregular forms. Derivation and compounding create new vocabulary.","grammar_notes":["Do not confuse grammatical -s with plural -s.","Irregular forms such as went, better and children must be learned as lexical forms."]}'::jsonb,ARRAY['morphology','plural','tense','suffix','word formation','phrasal verb'],'foundational','active','original_authored','messinho_original'),
('en.semantics.discourse',1,'en','pragmatics','Semantics and discourse','Hedging, aspect and discourse markers','{"terms":[{"term":"still","meaning_de":"continuing state or action; sometimes contrastive"},{"term":"yet","meaning_de":"up to now, often in questions and negatives"},{"term":"already","meaning_de":"before now or earlier than expected"},{"term":"actually","meaning_de":"in fact; often a correction or clarification, not German aktuell"},{"term":"might","meaning_de":"possibility with limited certainty"},{"term":"rather","meaning_de":"preference, degree or correction depending on context"}],"examples":[{"text":"He is not ready yet.","meaning":"The expected state has not been reached."},{"text":"He is still improving.","meaning":"An ongoing process."},{"text":"Actually, he played as a full-back.","meaning":"Correction or clarification."}],"explanation":"English discourse markers and aspect distinguish expectation, duration, contrast and certainty. Words such as still, yet, already, actually and rather have context-sensitive meanings. Modal verbs express possibility, obligation, ability or prediction; they do not all indicate certainty.","grammar_notes":["Preserve differences between may, might, must and should.","Do not translate false friends mechanically."]}'::jsonb,ARRAY['hedging','negation','yet','still','already','actually','however','modality'],'intermediate','active','original_authored','messinho_original'),
('es.grammar.clauses_negation',1,'es','grammar','Sintaxis','Oraciones, preguntas y negación','{"terms":[{"term":"aunque","meaning_de":"obwohl; auch wenn, mit Moduswahl nach Bedeutung"},{"term":"que","meaning_de":"leitet häufig einen Nebensatz ein"},{"term":"si","meaning_de":"wenn oder ob; Konstruktion beachten"}],"examples":[{"text":"Entrenamos mañana.","meaning":"Das Subjekt nosotros ist in der Verbform enthalten."},{"text":"No juega hoy.","meaning":"Negation vor dem Verb."},{"text":"No creo que esté listo.","meaning":"Negation und Subjuntivo in der abhängigen Aussage."}],"explanation":"El español permite omitir el sujeto cuando la forma verbal lo identifica. El orden sujeto-verbo-complemento es frecuente, pero puede cambiar para destacar información. La negación suele colocarse delante del verbo; los pronombres de objeto siguen reglas de posición propias.","grammar_notes":["Subjekt nicht ergänzen, wenn es im Kontext nicht benötigt wird.","Die Wahl des Subjuntivo hängt von Bedeutung und Satzstruktur ab."]}'::jsonb,ARRAY['sintaxis','orden de palabras','negación','subordinada','pronombres'],'intermediate','active','original_authored','messinho_original'),
('es.lexicon.football_core',1,'es','lexicon','Vocabulario de fútbol','Léxico del fútbol y del scouting','{"terms":[{"term":"central","meaning_de":"Innenverteidiger"},{"term":"lateral","meaning_de":"Außenverteidiger"},{"term":"mediocentro defensivo","meaning_de":"defensiver Mittelfeldspieler"},{"term":"interior","meaning_de":"zentraler Mittelfeldspieler"},{"term":"extremo","meaning_de":"Flügelspieler"},{"term":"delantero centro","meaning_de":"Mittelstürmer"},{"term":"presión alta","meaning_de":"hohes Pressing"},{"term":"desmarque","meaning_de":"Freilaufbewegung"},{"term":"pase filtrado","meaning_de":"Steilpass"},{"term":"rendimiento","meaning_de":"Leistung"}],"examples":[{"text":"El mediocentro defensivo protege el espacio delante de la defensa.","meaning":"Taktische Rollenbeschreibung."},{"text":"El extremo busca el desmarque a la espalda del lateral.","meaning":"Lauf in den Raum hinter den Außenverteidiger."}],"explanation":"Vocabulario original de fútbol en español. Hay variación regional entre España y América Latina; la posición debe interpretarse según el sistema táctico.","grammar_notes":["Varianten como volante, pivote y mediocentro dependen de la región y del sistema."]}'::jsonb,ARRAY['fútbol','scouting','posiciones','táctica','rendimiento'],'foundational','active','original_authored','messinho_original'),
('es.morphology.conjugation',1,'es','grammar','Morfología','Conjugación verbal y concordancia','{"terms":[{"term":"juega / jugaron / jugará","meaning_de":"Präsens, Vergangenheit und Zukunft"},{"term":"ha mejorado","meaning_de":"Pretérito perfecto compuesto"},{"term":"jugándolo","meaning_de":"Gerundium mit angehängtem Objektpronomen"},{"term":"rápido / rápidamente","meaning_de":"Adjektiv und abgeleitetes Adverb"}],"examples":[{"text":"La jugadora rápida ha mejorado.","meaning":"Femininum, Adjektivkongruenz und Perfekt."},{"text":"Lo está analizando.","meaning":"Objektpronomen vor der Verlaufsform."},{"text":"Quiero evaluarlo.","meaning":"Objektpronomen am Infinitiv."}],"explanation":"El español marca persona, número, tiempo, aspecto y modo mediante la conjugación. Los sustantivos tienen género y número; determinantes y adjetivos suelen concordar. Los pronombres de objeto pueden aparecer antes del verbo conjugado o unidos al infinitivo, gerundio e imperativo afirmativo.","grammar_notes":["Subjuntivo und indicativo unterscheiden; der Modus hängt von der Konstruktion ab.","Objektpronomen können an Infinitiv, Gerundium und bejahenden Imperativ angehängt werden."]}'::jsonb,ARRAY['morfología','conjugación','género','número','participio','subjuntivo'],'foundational','active','original_authored','messinho_original'),
('es.semantics.discourse',1,'es','pragmatics','Semántica y discurso','Matices, modalidad y conectores','{"terms":[{"term":"ser","meaning_de":"Identität, Klassifikation oder relativ stabile Eigenschaft je nach Konstruktion"},{"term":"estar","meaning_de":"Zustand, Ort oder Ergebniszustand je nach Konstruktion"},{"term":"por","meaning_de":"Grund, Weg, Austausch oder Zeitraum je nach Kontext"},{"term":"para","meaning_de":"Ziel, Zweck, Empfänger oder Frist"},{"term":"todavía","meaning_de":"noch; weiterhin"},{"term":"ya","meaning_de":"bereits; schon; nun"},{"term":"quizás","meaning_de":"vielleicht; möglicherweise"}],"examples":[{"text":"Está cansado, pero sigue entrenando.","meaning":"Zustand und Kontrast."},{"text":"Quizás mejore esta temporada.","meaning":"Unsicherheit; keine Gewissheit."},{"text":"Entrena para mejorar.","meaning":"Zweck mit para."}],"explanation":"La interpretación depende de distinciones como ser/estar, por/para, todavía/ya y de los conectores de contraste. El subjuntivo puede expresar deseo, duda, valoración o situaciones no presentadas como hechos. La negación y la incertidumbre deben conservarse.","grammar_notes":["Ser/estar nicht mit einer einzigen deutschen Entsprechung abbilden.","Por/para anhand der konkreten semantischen Funktion bestimmen."]}'::jsonb,ARRAY['ser','estar','por','para','todavía','ya','quizás','subjuntivo','contraste'],'intermediate','active','original_authored','messinho_original'),
('fr.grammar.pronouns_negation',1,'fr','grammar','Syntaxe','Pronoms clitiques, négation et questions','{"terms":[{"term":"le / la / les","meaning_de":"direkte Objektpronomen"},{"term":"lui / leur","meaning_de":"indirekte Objektpronomen"},{"term":"ne ... pas","meaning_de":"übliche Verneinung"},{"term":"est-ce que","meaning_de":"Fragekonstruktion ohne Inversion"}],"examples":[{"text":"Je le connais.","meaning":"Le pronom objet précède le verbe."},{"text":"Il ne joue pas aujourd''hui.","meaning":"Négation standard."},{"text":"Est-ce qu''il vient demain ?","meaning":"Question avec est-ce que."}],"explanation":"Les pronoms compléments se placent généralement avant le verbe conjugué, selon un ordre déterminé. La négation standard encadre le verbe avec ne et pas, même si ne disparaît souvent dans la langue parlée. Les questions peuvent utiliser l''intonation, est-ce que ou l''inversion.","grammar_notes":["Bei Infinitivkonstruktionen steht das Pronomen oft direkt vor dem Infinitiv.","Umgangssprachlicher Wegfall von ne ist nicht automatisch ein Bedeutungswechsel."]}'::jsonb,ARRAY['pronoms','clitiques','négation','ne pas','ordre des mots','question'],'intermediate','active','original_authored','messinho_original'),
('fr.lexicon.football_core',1,'fr','lexicon','Vocabulaire du football','Lexique du football et du recrutement','{"terms":[{"term":"défenseur central","meaning_de":"Innenverteidiger"},{"term":"latéral","meaning_de":"Außenverteidiger"},{"term":"milieu défensif","meaning_de":"defensiver Mittelfeldspieler"},{"term":"milieu relayeur","meaning_de":"verbindender zentraler Mittelfeldspieler"},{"term":"ailier","meaning_de":"Flügelspieler"},{"term":"avant-centre","meaning_de":"Mittelstürmer"},{"term":"pressing","meaning_de":"koordiniertes Anlaufen"},{"term":"appel en profondeur","meaning_de":"Tiefenlauf"},{"term":"jeu entre les lignes","meaning_de":"Spiel zwischen den Linien"},{"term":"recrutement","meaning_de":"Spielerrekrutierung"}],"examples":[{"text":"Le milieu défensif protège la défense.","meaning":"Rollenbeschreibung."},{"text":"L''ailier attaque l''espace dans le dos du latéral.","meaning":"Taktische Laufbewegung."}],"explanation":"Vocabulaire original du football français. Les noms de postes et les expressions tactiques varient selon les clubs et les pays francophones.","grammar_notes":["Bei Begriffen aus Frankreich, Kanada und Nordafrika regionale Varianten berücksichtigen."]}'::jsonb,ARRAY['football','recrutement','postes','tactique','analyse'],'foundational','active','original_authored','messinho_original'),
('fr.morphology.conjugation',1,'fr','grammar','Morphologie','Conjugaison, accords et formation des mots','{"terms":[{"term":"il joue / ils jouent","meaning_de":"Die Endung ist schriftlich sichtbar, aber oft nicht hörbar"},{"term":"il a joué","meaning_de":"Passé composé mit avoir"},{"term":"elle est partie","meaning_de":"Passé composé mit être und Angleichung des Partizips"},{"term":"rapide / rapidement","meaning_de":"Adjektiv und abgeleitetes Adverb"}],"examples":[{"text":"Une joueuse rapide a marqué.","meaning":"Femininum und Adjektivkongruenz."},{"text":"Les joueurs sont arrivés.","meaning":"Plural und Partizipangleichung mit être."},{"text":"Il a bien joué.","meaning":"Passé composé."}],"explanation":"Le français marque la personne, le nombre, le temps et le mode par la conjugaison. Les noms ont un genre grammatical; les déterminants et adjectifs s''accordent généralement en genre et en nombre. Les formes écrites et orales peuvent différer fortement.","grammar_notes":["Die hörbare Form zeigt nicht immer alle schriftlichen Endungen.","Partizipangleichung hängt von Hilfsverb und Konstruktion ab."]}'::jsonb,ARRAY['morphologie','conjugaison','accord','genre','nombre','participe passé'],'foundational','active','original_authored','messinho_original'),
('fr.semantics.discourse',1,'fr','pragmatics','Sémantique et discours','Nuances, modalité et connecteurs','{"terms":[{"term":"pourtant","meaning_de":"trotzdem; markiert einen Gegensatz zur Erwartung"},{"term":"cependant","meaning_de":"jedoch; allerdings"},{"term":"encore","meaning_de":"noch, wieder oder weiterhin"},{"term":"déjà","meaning_de":"bereits; schon"},{"term":"plutôt","meaning_de":"eher; vielmehr"},{"term":"bien que","meaning_de":"obwohl; leitet üblicherweise den Subjonctif ein"}],"examples":[{"text":"Il est fort, pourtant il doit progresser.","meaning":"Kontrast trotz positiver Eigenschaft."},{"text":"Il n''est pas encore prêt.","meaning":"Ein Zustand ist bisher nicht erreicht."},{"text":"Bien qu''il soit jeune, il joue avec maturité.","meaning":"Konzessiver Nebensatz mit Subjonctif."}],"explanation":"Les connecteurs français expriment contraste, concession, conséquence et réserve. Encore, déjà, toujours et plutôt changent de sens selon le contexte. Le subjonctif apparaît notamment après certaines expressions de volonté, de doute, de nécessité ou d''émotion.","grammar_notes":["Unterschied zwischen indicatif und subjonctif nach der auslösenden Konstruktion beachten.","Negation und Einschränkung nicht abschwächen."]}'::jsonb,ARRAY['pourtant','cependant','encore','déjà','plutôt','subjonctif','modalité'],'intermediate','active','original_authored','messinho_original')
